{
  "concepts": [
    {
      "conditions": [],
      "definition": "The engineering Ontology is the single semantic truth of a designed boundary. Diagrams, matrices, IACS, APIs, operation registers, SDK/CLI surfaces, schemas, codecs, manifests, catalogues, target architecture, modules and proof inventories preserve it through the specified design and requirement paths; they are not independent semantic authorities.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1084,
          "quote": "The Ontology is one semantic truth",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/DESIGN_MODULE.md#DESIGN_MODULE%2F5.%20Ontology-first%20design%2FOntology%20projection",
          "start_line": 1077
        }
      ],
      "key": "ontology",
      "label": "Engineering Ontology"
    },
    {
      "conditions": [],
      "definition": "A smallest parameterised atomic-function family derived by the Ontology to make entity lifecycles logically complete. Its derivation evidence relates discovered functionality, entity, atomic function or template, higher-order composition, effect class, required authority and disposition.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 968,
          "quote": "| Discovered functionality | Entity | Atomic function or template | Higher-order composition | Effect class | Required authority | Disposition |",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/DESIGN_MODULE.md#DESIGN_MODULE%2F5.%20Ontology-first%20design%2FAtomic%20functions%20and%20higher-order%20composition",
          "start_line": 968
        }
      ],
      "key": "atomic_function_family",
      "label": "Atomic function family"
    },
    {
      "conditions": [
        "The boundary has higher-order behaviour."
      ],
      "definition": "A declared governing composition and effect algebra. Typical categories are unit/lift, sequential composition, parallel/applicative composition, fold/evaluation, retry/recovery, recursion/fixed point and projection.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 980,
          "quote": "Typical categories include unit\nor lift, sequential composition, parallel or applicative composition, fold\nor evaluation, retry or recovery, recursion or fixed point, and\nprojection.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/DESIGN_MODULE.md#DESIGN_MODULE%2F5.%20Ontology-first%20design%2FAtomic%20functions%20and%20higher-order%20composition",
          "start_line": 977
        }
      ],
      "key": "higher_order_composition",
      "label": "Higher-order composition"
    },
    {
      "conditions": [],
      "definition": "One irreducible semantic design relation: atomic-function family, identity, authority transition, lifecycle relation, topology, effect, closure law or composition law that cannot honestly be composed from other accepted atoms while preserving meaning. Prime is decided at semantic-design altitude.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1002,
          "quote": "A Prime semantic atom is one irreducible design relation: an atomic\nfunction family, identity, authority transition, lifecycle relation,\ntopology, effect, closure law or composition law that cannot be expressed\nhonestly by composing other accepted atoms while preserving the same\nmeaning",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/DESIGN_MODULE.md#DESIGN_MODULE%2F5.%20Ontology-first%20design%2FPrime%20semantic%20atoms%20and%20admitted%20domain",
          "start_line": 998
        }
      ],
      "key": "prime_semantic_atom",
      "label": "Prime semantic atom"
    },
    {
      "conditions": [],
      "definition": "Design review of the complete candidate semantic-atom family and every proposed realisation projection, including all identities, authority transitions, lifecycle relations, topologies, functions, composition laws, effects and closure laws. Individual plausibility or a function-and-carrier-only pass does not establish whole-family Prime.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1028,
          "quote": "Prime review evaluates the complete candidate semantic-atom family and\nevery proposed realisation projection, not only functions, carriers or\neach atom in isolation.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/DESIGN_MODULE.md#DESIGN_MODULE%2F5.%20Ontology-first%20design%2FWhole-family%20Prime%20contraction",
          "start_line": 1026
        }
      ],
      "key": "prime_contraction",
      "label": "Whole-family Prime contraction"
    },
    {
      "conditions": [],
      "definition": "A realisation projection implements accepted semantic atoms. Prime-conformance applies to functions, classes, carrier types, top-level schema records and modules; source-code size and one-to-one atom correspondence are immaterial.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1113,
          "quote": "Prime-conformance applies to these realisation projections: functions,\nclasses, carrier types, top-level schema records and modules.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/DESIGN_MODULE.md#DESIGN_MODULE%2F6.%20Prime%20law",
          "start_line": 1111
        }
      ],
      "key": "realisation_projection",
      "label": "Realisation projection"
    },
    {
      "conditions": [],
      "definition": "The Irreducible Architectural Carrier Set is the smallest lawful top-level carrier family carrying a boundary's real functionality and authority flow. Example roles are source truth, admission, execution, yield/recovery, effect plan and public projection. It is an Ontology projection and declared carrier inventory, not an origin or replacement of semantic meaning.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1176,
          "quote": "The IACS is the smallest\nset of carriers required to carry the real functionality and authority\nflow of the boundary.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/DESIGN_MODULE.md#DESIGN_MODULE%2F6.%20Prime%20law%2FIrreducible%20architectural%20carrier%20set",
          "start_line": 1174
        }
      ],
      "key": "iacs",
      "label": "Irreducible Architectural Carrier Set"
    },
    {
      "conditions": [],
      "definition": "Payload detail inside a boundary that is not top-level by default.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1119,
          "quote": "- Subordinate Payload: payload detail that exists inside that boundary but\n  is not top-level by default;",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/DESIGN_MODULE.md#DESIGN_MODULE%2F6.%20Prime%20law",
          "start_line": 1118
        }
      ],
      "key": "subordinate_payload",
      "label": "Subordinate Payload"
    },
    {
      "conditions": [],
      "definition": "The explicit test preceding a Subordinate Payload's promotion to a top-level architectural type, including class, dataclass, TypedDict, enum or named schema record.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1245,
          "quote": "A top-level class, dataclass, TypedDict, enum or named schema record\njustifies its existence as an architectural boundary, not merely as\npayload detail",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/DESIGN_MODULE.md#DESIGN_MODULE%2F6.%20Prime%20law%2FPromotion%20test",
          "start_line": 1242
        }
      ],
      "key": "promotion_test",
      "label": "Promotion Test"
    },
    {
      "conditions": [],
      "definition": "Design debt in which payload detail becomes peer types because typing feels difficult; internal records become public schema without a new authoritative boundary; near-identical top-level types proliferate where one carrier family suffices; or one migration silently becomes parallel schema migrations.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1281,
          "quote": "Boundary Inflation is design debt, not\nprogress",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/DESIGN_MODULE.md#DESIGN_MODULE%2F6.%20Prime%20law%2FBoundary%20inflation%20prohibition",
          "start_line": 1280
        }
      ],
      "key": "boundary_inflation",
      "label": "Boundary Inflation"
    },
    {
      "conditions": [
        "A realisation derives from an existing design line, released tenant or reference implementation."
      ],
      "definition": "A derivation chain through constitutional WHAT, reference design, target Ontology and reference-to-Ontology mapping, target design mapping, target module boundary assets and implementation. It prevents incidental reference drift, delivery quirks, helper sprawl and accidental authority paths from being imported without an audit trail.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1291,
          "quote": "The required derivation\nevidence is: (1) constitutional WHAT; (2) reference design; (3) target\nOntology and reference-to-Ontology mapping; (4) target design mapping; (5)\ntarget module boundary assets; (6) implementation.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/DESIGN_MODULE.md#DESIGN_MODULE%2F6.%20Prime%20law%2FReference-derived%20module%20design",
          "start_line": 1288
        }
      ],
      "key": "reference_derivation",
      "label": "Reference-derived module design"
    },
    {
      "conditions": [],
      "definition": "One complete design asset comprising distinct domain, execution and lifecycle views, normally Mermaid classDiagram, sequenceDiagram and stateDiagram-v2. These are fidelity-checked Ontology projections and together the sign-off surface for domain identity, authority, behaviour, lifecycle and axiom conformance.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1327,
          "quote": "The asset contains all three views: a Mermaid `classDiagram` domain model;\na Mermaid `sequenceDiagram` execution model; and a Mermaid\n`stateDiagram-v2` lifecycle model.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/DESIGN_MODULE.md#DESIGN_MODULE%2F7.%20Ontology%20and%20three-view%20design%20gate",
          "start_line": 1325
        }
      ],
      "key": "three_view_asset",
      "label": "Three-view design asset"
    },
    {
      "conditions": [
        "An accepted material-frame basis and a proposed bounded action are given."
      ],
      "definition": "The sufficiency property of selected method basis plus accepted design for recovering every governing relation in an action's causally closed affected set and deciding preserves, changes, duplicates or violates. Method specifies required relations and reasoning; design supplies concrete invariant values. This is durable reasoning state, not dialogue, memory, folklore or a separate documentation package.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1374,
          "quote": "the selected method describes which relations\nare required and how to reason about them; the accepted design supplies\nthe concrete invariant values.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/DESIGN_MODULE.md#DESIGN_MODULE%2F7.%20Ontology%20and%20three-view%20design%20gate%2FInvariant%20reconstruction%20sufficiency%20%28UP-018%29",
          "start_line": 1372
        }
      ],
      "key": "invariant_reconstruction",
      "label": "Invariant reconstruction sufficiency"
    },
    {
      "conditions": [],
      "definition": "The structural Ontology projection for the active boundary, showing domain identities/cardinalities, ownership/invariants/lifecycle relationships, boundary-crossing atomic functions and inputs/outputs, shape-determining composition, IACS-to-Prime mappings, subordinate and effect-edge payloads, downstream projections, deferred families, authority and visibility, and genuine composition/containment/association/variant structure.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1433,
          "quote": "The `classDiagram` is the structural domain projection of the Ontology",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/DESIGN_MODULE.md#DESIGN_MODULE%2F7.%20Ontology%20and%20three-view%20design%20gate%2FDomain%20model",
          "start_line": 1431
        }
      ],
      "key": "domain_model",
      "label": "Domain model"
    },
    {
      "conditions": [],
      "definition": "The behavioural projection of Ontology functions and authority, showing supported execution from admitted input to result or truthful stop, with owners and required authority for every decision, admission, execution, projection and effect boundary.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1457,
          "quote": "It shows the supported\nexecution path from admitted input to result or truthful stop, and names\nthe owner and required authority of every decision, admission, execution,\nprojection and effect boundary.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/DESIGN_MODULE.md#DESIGN_MODULE%2F7.%20Ontology%20and%20three-view%20design%20gate%2FSequence%20model",
          "start_line": 1454
        }
      ],
      "key": "sequence_model",
      "label": "Sequence model"
    },
    {
      "conditions": [],
      "definition": "The lifecycle projection of Ontology entities, covering the complete admitted lifecycle of the active boundary, including every refusal, blocked, continuation, retry, escalation and terminal state that boundary can produce.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1473,
          "quote": "It shows the complete admitted lifecycle for\nthe active boundary, including refusal, blocked, continuation, retry,\nescalation and terminal states that the boundary can produce.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/DESIGN_MODULE.md#DESIGN_MODULE%2F7.%20Ontology%20and%20three-view%20design%20gate%2FState%20model",
          "start_line": 1471
        }
      ],
      "key": "state_model",
      "label": "State model"
    },
    {
      "conditions": [],
      "definition": "Design-pack assessment of each applicable product, graph, language, runtime, handler and module axiom. Minimum columns are Axiom, Ontology evidence, Authority, Domain evidence, Sequence evidence, State evidence, Native enforcement, Admission/compiler enforcement, Verdict and Gap owner. Its verdicts and direct core results are assessment data, distinct from acceptance.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1486,
          "quote": "| Axiom | Ontology evidence | Authority | Domain evidence | Sequence evidence | State evidence | Native enforcement | Admission/compiler enforcement | Verdict | Gap owner |",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/DESIGN_MODULE.md#DESIGN_MODULE%2F7.%20Ontology%20and%20three-view%20design%20gate%2FCross-view%20axiom%20evaluation",
          "start_line": 1486
        }
      ],
      "key": "axiom_evaluation",
      "label": "Cross-view axiom evaluation"
    },
    {
      "conditions": [],
      "definition": "The design authority's separate acceptance decisions for the Ontology and design pack. Each consumes availability and assessment, including decision completeness, axiom results and cross-view proofs. accepted denotes accept, mapped to satisfied for the predicate that this candidate is accepted at its declared design-gate boundary; pack production and passing assessments are not acceptance.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1559,
          "quote": "The Ontology verdict and the design verdict are each an acceptance\nresult: a decision that consumes the results of assessment, distinct from\nthem.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/DESIGN_MODULE.md#DESIGN_MODULE%2F7.%20Ontology%20and%20three-view%20design%20gate%2FGate%20and%20retrospective%20work",
          "start_line": 1557
        }
      ],
      "key": "design_gate",
      "label": "Ontology and design acceptance gate"
    },
    {
      "conditions": [
        "A material semantic boundary is considered."
      ],
      "definition": "A subordinate projection exposing abstract data types, identity/key structures, algorithms, algebraic laws, mutation/effect boundaries, selected implementations and domain-to-computational mappings. It reveals repeated machinery hidden by domain identities but cannot decide semantic identity, ownership or authority.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1651,
          "quote": "the design projects the\ndomain design into its computational realisation: abstract data types,\nidentity and key structures, algorithms, algebraic laws, mutation and\neffect boundaries, selected implementations, and domain-to-computational\nmappings.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/DESIGN_MODULE.md#DESIGN_MODULE%2F7.%20Ontology%20and%20three-view%20design%20gate%2FComputational%20realisation%20projection%20%28UP-019%29",
          "start_line": 1647
        }
      ],
      "key": "computational_projection",
      "label": "Computational realisation projection"
    },
    {
      "conditions": [],
      "definition": "Optional world-model justification: a Markov object is a candidate identity-bearing, stable self-bounding cut whose effective blanket separates identity-bearing from context-bearing structure. IACS analogises the smallest lawful cut; promotion asks independent boundary authority; inflation mistakes fragments for peer objects; strong boundary typing avoids fuzzy, reconstructive or controller-owned identity.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1730,
          "quote": "It treats a Markov object\nas a candidate identity-bearing cut: a stable self-bounding pattern whose\neffective blanket separates what is load-bearing for identity from what is\nload-bearing for context.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/DESIGN_MODULE.md#DESIGN_MODULE%2F8.%20Theoretical%20framing",
          "start_line": 1727
        }
      ],
      "key": "theoretical_framing",
      "label": "Optional theoretical framing"
    },
    {
      "conditions": [
        "The profile governs a realisation boundary."
      ],
      "definition": "Recommended role taxonomy: carrier modules define typed immutable inputs, outputs, contracts, transitions, records or envelopes; semantic kernels transform carriers without effects; effect shells emit events, publish files, call networks/subprocesses, persist or deliver to operators; projection modules derive reports/read models from authoritative truth; adapters translate external boundaries to internal carriers without inventing law; constructors/materialisers write built/generated artifacts from admitted carriers and explicit plans. These roles bound traversal reasoning and make recurrence visible, rather than impose naming ceremony.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1752,
          "quote": "modules should be\nclassified by role",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/DESIGN_MODULE.md#DESIGN_MODULE%2F9.%20Module%20taxonomy",
          "start_line": 1750
        }
      ],
      "key": "module_roles",
      "label": "Module role taxonomy"
    },
    {
      "conditions": [],
      "definition": "The profile's preferred realisation discipline uses an algebraic primitive with projections rather than multiple local decision systems, and prefers total functions, closed enums, explicit state and deterministic folds.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1793,
          "quote": "Projects using this profile prefer one algebraic primitive plus\nprojections over several local decision systems, and prefer total\nfunctions, closed enums, explicit state and deterministic folds",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/DESIGN_MODULE.md#DESIGN_MODULE%2F10.%20Realisation%20rules",
          "start_line": 1791
        }
      ],
      "key": "realisation_discipline",
      "label": "Preferred realisation discipline"
    },
    {
      "conditions": [],
      "definition": "A semantic function's outcomes are Product domain values, including unsupported or rejected outcomes where used. They are distinct from method results: an evaluation consuming those outcomes returns its own core result value.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1819,
          "quote": "The outcome values a\nsemantic function returns are the Product's domain values, not results of\nthis method; an evaluation that consumes them returns its own core value",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/DESIGN_MODULE.md#DESIGN_MODULE%2F10.%20Realisation%20rules%2FTotality",
          "start_line": 1816
        }
      ],
      "key": "product_outcome",
      "label": "Product outcome versus method result"
    },
    {
      "conditions": [
        "A boundary governs, observes, routes, audits or evaluates another actor, executor, builder or substrate."
      ],
      "definition": "A governance surface describes state, boundary and admissible routes. Lawful publication includes current state, preserved structure, unmet pressure or unresolved identities, route eligibility, lawful edit/proof frontier, admitted policy identity and prior-turn/run continuity. Strategy surfaces prescribe how another actor should work.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1884,
          "quote": "Governance surfaces describe the state, boundary\nand admissible routes; strategy surfaces prescribe how another actor\nshould do the work.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/DESIGN_MODULE.md#DESIGN_MODULE%2F10.%20Realisation%20rules%2FGovernance%20and%20strategy%20separation",
          "start_line": 1882
        }
      ],
      "key": "governance_boundary",
      "label": "Governance and strategy boundary"
    },
    {
      "conditions": [
        "A realisation boundary is lawfully open for migration, refactor or bounded implementation work."
      ],
      "definition": "Boundary-local improvement subordinate to constitutional truth, declared module ownership evidence and functional equivalence. Examples include removing parser re-entry on locally assembled truth, consolidating local route logic, improving a local algorithm or scan, and simplifying proof fixtures/tests without changing their module claims.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1896,
          "quote": "This does not\noutrank constitutional truth, declared module ownership evidence or\nfunctional equivalence; it is subordinate to them.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/DESIGN_MODULE.md#DESIGN_MODULE%2F10.%20Realisation%20rules%2FOpportunistic%20optimisation",
          "start_line": 1893
        }
      ],
      "key": "opportunistic_optimisation",
      "label": "Opportunistic optimisation"
    },
    {
      "conditions": [
        "The same realisation pattern appears across more than one processed boundary."
      ],
      "definition": "Review of a commonisation candidate rather than another purely local cleanup. Candidates usually are not product truth, are authority-neutral, recur across at least two tickets or module boundaries, and work through local adapters without changing semantic ownership. Typical cases include expectation derivation, nested contract/policy carriers, proof fixtures, effect-edge plans and constructors without semantic law.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1933,
          "quote": "When the same realisation pattern appears across more than one processed\nboundary, review treats that pattern as a commonisation candidate rather\nthan as another purely local clean-up",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/DESIGN_MODULE.md#DESIGN_MODULE%2F10.%20Realisation%20rules%2FRecurrence%20extraction",
          "start_line": 1931
        }
      ],
      "key": "recurrence_extraction",
      "label": "Recurrence extraction"
    },
    {
      "conditions": [
        "A ticket applies the profile to its boundary and claims that boundary has been processed."
      ],
      "definition": "A bounded check against accepted design and the exact closure claim, reconstructing the claim's causal closure from governing requirements through Ontology, Prime atoms, IACS, views, target modules, implementation and module-owned proof. This is not a review of the whole Product/history or merely previous findings.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1996,
          "quote": "The check reconstructs the complete selected function from governing\nrequirements through the accepted Ontology, Prime atoms, IACS, views,\ntarget modules, implementation and module-owned proof",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/DESIGN_MODULE.md#DESIGN_MODULE%2F10.%20Realisation%20rules%2FPost-ticket%20design%20review",
          "start_line": 1993
        }
      ],
      "key": "post_ticket_review",
      "label": "Post-ticket design review"
    },
    {
      "conditions": [],
      "definition": "An interface family has one authoritative source truth consumed by downstream interfaces. Bleed occurs when an interface reconstructs another's truth, projections decide closure, reports/prompts decide admission, wrappers decide kernel meaning or adapters invent semantics.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 2066,
          "quote": "each interface family has\none authoritative source truth; downstream interfaces consume that truth;\ncrossing an interface boundary does not create a new semantic centre.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/DESIGN_MODULE.md#DESIGN_MODULE%2F10.%20Realisation%20rules%2FInterface%20bleed%20prohibition",
